import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Project 2: Create a PPT Report (Intermediate Level)","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-5/project-2.md","filePath":"en/modules/module-5/project-2.md"}'),i={name:"en/modules/module-5/project-2.md"};function o(r,e,l,p,d,h){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="project-2-create-a-ppt-report-intermediate-level" tabindex="-1">Project 2: Create a PPT Report (Intermediate Level) <a class="header-anchor" href="#project-2-create-a-ppt-report-intermediate-level" aria-label="Permalink to &quot;Project 2: Create a PPT Report (Intermediate Level)&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Learn to have Codex search the web for materials and generate a presentation ⏱️ <strong>Estimated Time</strong>: 30 minutes 🎯 <strong>Skills learned</strong>: Web Search, content organization, Skill calling</p></blockquote><hr><h2 id="i-task-description" tabindex="-1">I. Task Description <a class="header-anchor" href="#i-task-description" aria-label="Permalink to &quot;I. Task Description&quot;">​</a></h2><p>Have Codex generate a themed presentation based on online research.</p><hr><h2 id="ii-operation-steps" tabindex="-1">II. Operation Steps <a class="header-anchor" href="#ii-operation-steps" aria-label="Permalink to &quot;II. Operation Steps&quot;">​</a></h2><h3 id="step-1-choose-a-topic" tabindex="-1">Step 1: Choose a Topic <a class="header-anchor" href="#step-1-choose-a-topic" aria-label="Permalink to &quot;Step 1: Choose a Topic&quot;">​</a></h3><p>Pick a topic you&#39;re interested in, such as:</p><ul><li>&quot;AI Development Trends in 2026&quot;</li><li>&quot;Best Practices for Remote Work&quot;</li><li>&quot;Healthy Eating Guide&quot;</li><li>&quot;Current State of the New Energy Vehicle Market&quot;</li></ul><h3 id="step-2-have-codex-generate-an-outline" tabindex="-1">Step 2: Have Codex Generate an Outline <a class="header-anchor" href="#step-2-have-codex-generate-an-outline" aria-label="Permalink to &quot;Step 2: Have Codex Generate an Outline&quot;">​</a></h3><p>Open Codex and type:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me make a presentation about &quot;[your topic]&quot;. Requirements:</span></span>
<span class="line"><span>1. About 10-15 pages</span></span>
<span class="line"><span>2. Include cover, table of contents, main point analysis, case studies, and summary</span></span>
<span class="line"><span>3. Each page should have a title and 3-5 key points</span></span>
<span class="line"><span>4. Style should be clean and professional</span></span>
<span class="line"><span>Give me an outline first, and wait for my confirmation before starting the actual creation.</span></span></code></pre></div><h3 id="step-3-review-the-outline" tabindex="-1">Step 3: Review the Outline <a class="header-anchor" href="#step-3-review-the-outline" aria-label="Permalink to &quot;Step 3: Review the Outline&quot;">​</a></h3><p>Codex will generate a structure like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>📊 [Topic] Presentation Outline</span></span>
<span class="line"><span>Page 1: Cover — title, subtitle, date</span></span>
<span class="line"><span>Page 2: Table of Contents — background intro, core trends, case studies, future outlook, summary</span></span>
<span class="line"><span>... (more pages)</span></span></code></pre></div><p>Check whether the outline covers everything you care about. Adjust if needed.</p><h3 id="step-4-have-codex-search-the-web-and-fill-in-content" tabindex="-1">Step 4: Have Codex Search the Web and Fill in Content <a class="header-anchor" href="#step-4-have-codex-search-the-web-and-fill-in-content" aria-label="Permalink to &quot;Step 4: Have Codex Search the Web and Fill in Content&quot;">​</a></h3><p>After confirming the outline, type:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The outline looks good, please start creating.</span></span>
<span class="line"><span>Note:</span></span>
<span class="line"><span>1. Search the web for the latest materials to fill in the content</span></span>
<span class="line"><span>2. Every claim should be supported by data or case studies</span></span>
<span class="line"><span>3. Cite sources clearly</span></span>
<span class="line"><span>4. Use a professional business style</span></span></code></pre></div><h3 id="step-5-review-and-refine" tabindex="-1">Step 5: Review and Refine <a class="header-anchor" href="#step-5-review-and-refine" aria-label="Permalink to &quot;Step 5: Review and Refine&quot;">​</a></h3><p>After Codex finishes, review the generated content:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me check:</span></span>
<span class="line"><span>1. Are the data points up to date?</span></span>
<span class="line"><span>2. Is there any outdated information?</span></span>
<span class="line"><span>3. Is the language fluent?</span></span>
<span class="line"><span>4. Is the formatting consistent?</span></span></code></pre></div><p>Then make微调 based on Codex&#39;s suggestions.</p><hr><h2 id="iii-advanced-techniques" tabindex="-1">III. Advanced Techniques <a class="header-anchor" href="#iii-advanced-techniques" aria-label="Permalink to &quot;III. Advanced Techniques&quot;">​</a></h2><h3 id="add-charts" tabindex="-1">Add Charts <a class="header-anchor" href="#add-charts" aria-label="Permalink to &quot;Add Charts&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>On the &quot;Market Size&quot; page, help me generate a bar chart showing the data changes over the past 5 years.</span></span></code></pre></div><h3 id="translate-to-another-language" tabindex="-1">Translate to Another Language <a class="header-anchor" href="#translate-to-another-language" aria-label="Permalink to &quot;Translate to Another Language&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Translate this presentation into an English version.</span></span></code></pre></div><h3 id="export-in-different-formats" tabindex="-1">Export in Different Formats <a class="header-anchor" href="#export-in-different-formats" aria-label="Permalink to &quot;Export in Different Formats&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Save the content as a Markdown file so I can edit it later.</span></span></code></pre></div><hr><h2 id="iv-summary" tabindex="-1">IV. Summary <a class="header-anchor" href="#iv-summary" aria-label="Permalink to &quot;IV. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill Learned</th><th>Description</th></tr></thead><tbody><tr><td>Web Search</td><td>Have Codex search for the latest materials</td></tr><tr><td>Content Organization</td><td>Extract key information from search results</td></tr><tr><td>Skill Calling</td><td>Use the PPT generation skill</td></tr><tr><td>Iterative Optimization</td><td>Continuously refine results through follow-up prompts</td></tr></tbody></table><hr><h2 id="v-next-step" tabindex="-1">V. Next Step <a class="header-anchor" href="#v-next-step" aria-label="Permalink to &quot;V. Next Step&quot;">​</a></h2><p><a href="./project-3.html">→ Project 3: Build a Simple Website</a></p>`,38)])])}const b=a(i,[["render",o]]);export{u as __pageData,b as default};
